package com.inoculationbracelet;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * Draws the bracelet of inoculation icon whenever the player is not wearing one.
 * The icon comes from the item cache rather than a bundled image, so it always
 * matches whatever the item looks like in game.
 */
class InoculationBraceletOverlay extends Overlay
{
	private final InoculationBraceletPlugin plugin;
	private final InoculationBraceletConfig config;
	private final ItemManager itemManager;

	private BufferedImage braceletIcon;
	private boolean iconRequested;

	// Rescaling every frame would allocate a full image per frame, so the drawn icon and
	// its bounds are kept until the configured size changes.
	private BufferedImage scaledIcon;
	private Dimension scaledIconBounds;
	private int scaledIconWidth;

	@Inject
	private InoculationBraceletOverlay(InoculationBraceletPlugin plugin, InoculationBraceletConfig config, ItemManager itemManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isBraceletMissing())
		{
			return null;
		}

		BufferedImage icon = iconAtConfiguredSize();
		if (icon == null)
		{
			return null;
		}

		graphics.drawImage(icon, 0, 0, null);
		return scaledIconBounds;
	}

	private BufferedImage iconAtConfiguredSize()
	{
		if (braceletIcon == null)
		{
			requestIcon();
			return null;
		}

		int width = config.iconSize();
		if (scaledIcon != null && scaledIconWidth == width)
		{
			return scaledIcon;
		}

		int height = Math.round(braceletIcon.getHeight() * width / (float) braceletIcon.getWidth());
		scaledIcon = ImageUtil.resizeImage(braceletIcon, width, height);
		scaledIconBounds = new Dimension(scaledIcon.getWidth(), scaledIcon.getHeight());
		scaledIconWidth = width;
		return scaledIcon;
	}

	// The item sprite is filled in asynchronously, so it can still be blank when first
	// asked for. The one-shot flag keeps render from stacking a load listener per frame.
	private void requestIcon()
	{
		if (iconRequested)
		{
			return;
		}

		iconRequested = true;
		AsyncBufferedImage loadingIcon = itemManager.getImage(ItemID.JEWL_BRACELET_OF_INNOCULATION);
		loadingIcon.onLoaded(() ->
		{
			braceletIcon = loadingIcon;
			scaledIcon = null;
		});
	}
}

