package com.inoculationbracelet;

import java.time.Instant;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(InoculationBraceletConfig.GROUP)
public interface InoculationBraceletConfig extends Config
{
	String GROUP = "inoculationbracelet";
	String SUGGEST_BUTTON_KEY = "suggestButton";
	String SUPPORT_BUTTON_KEY = "supportButton";

	@ConfigSection(
		name = "Reminder",
		description = "How the reminder icon is drawn",
		position = 0
	)
	String reminderSection = "reminderSection";

	@ConfigItem(
		keyName = "iconSize",
		name = "Icon size",
		description = "Width of the icon in pixels",
		section = reminderSection,
		position = 0
	)
	@Range(min = 16, max = 128)
	default int iconSize()
	{
		return 36;
	}

	@ConfigSection(
		name = "Feedback",
		description = "Suggestions, bug reports, and support",
		position = 99
	)
	String feedbackSection = "feedbackSection";

	// ConfigPanel renders a label for every config item but only builds an editor for
	// the types it knows about. Instant has no editor, so this row shows as read-only
	// text, and the text lives in the annotation so it can never go stale in a profile.
	@ConfigItem(
		keyName = "aboutNote",
		name = "<html><body style='margin:0;width:165px'>Based on the Ring of Recoil Notifier by delps1001.</body></html>",
		description = "",
		section = feedbackSection,
		position = 0
	)
	default Instant aboutNote()
	{
		return Instant.EPOCH;
	}

	@ConfigItem(
		keyName = SUGGEST_BUTTON_KEY,
		name = "Suggest a feature",
		description = "Have an idea or found a bug? Click the box to open the GitHub issues page",
		section = feedbackSection,
		position = 1
	)
	default boolean suggestButton()
	{
		return false;
	}

	@ConfigItem(
		keyName = SUPPORT_BUTTON_KEY,
		name = "Buy me a coffee ❤",
		description = "Enjoying the plugin? Click the box to open the Ko-fi page",
		section = feedbackSection,
		position = 2
	)
	default boolean supportButton()
	{
		return false;
	}
}

