package com.inoculationbracelet;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.LinkBrowser;

@PluginDescriptor(
	name = "Inoculation Bracelet Notifier",
	description = "Shows an icon when you are not wearing a bracelet of inoculation",
	tags = {"jake", "inoculation", "bracelet", "disease", "diseased", "immunity", "maggot", "maggots", "maggot king", "king", "boss", "notifier", "notify", "reminder", "warning", "missing", "unequipped", "equipment", "gear", "jewellery", "jewelry", "ruby", "zogre", "zogres", "skogre", "jiggig", "icon", "overlay"}
)
public class InoculationBraceletPlugin extends Plugin
{
	private static final String SUGGESTIONS_URL = "https://github.com/jakevollkommer/inoculation-bracelet-notifier/issues";
	private static final String SUPPORT_URL = "https://ko-fi.com/jakevollkommer";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InoculationBraceletOverlay overlay;

	private boolean braceletEquipped;

	@Provides
	InoculationBraceletConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InoculationBraceletConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Worn equipment fires no container event when the plugin is enabled mid-session,
		// so read what is already on the player once.
		clientThread.invokeLater(this::readEquippedBracelet);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		braceletEquipped = false;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			readEquippedBracelet();
		}
	}

	// The config panel cannot host real buttons, so the Feedback "buttons" are checkboxes
	// that act as buttons: any click of the box, tick or untick, opens the link.
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!InoculationBraceletConfig.GROUP.equals(event.getGroup()) || event.getNewValue() == null)
		{
			return;
		}

		if (InoculationBraceletConfig.SUGGEST_BUTTON_KEY.equals(event.getKey()))
		{
			LinkBrowser.browse(SUGGESTIONS_URL);
			return;
		}

		if (InoculationBraceletConfig.SUPPORT_BUTTON_KEY.equals(event.getKey()))
		{
			LinkBrowser.browse(SUPPORT_URL);
		}
	}

	// Asked by the overlay every frame. The game state gate keeps the last session's
	// equipment from putting the icon on the login screen.
	boolean isBraceletMissing()
	{
		return !braceletEquipped && client.getGameState() == GameState.LOGGED_IN;
	}

	private void readEquippedBracelet()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		braceletEquipped = equipment != null && equipment.contains(ItemID.JEWL_BRACELET_OF_INNOCULATION);
	}
}
